insert into public.assistant_knowledge_documents (slug, title, category, body) values
('platform-model', 'TradeSignal product model', 'product', $$TradeSignal is a UK B2B buying-intent and opportunity intelligence platform. It finds businesses entering a buying window, explains why they are relevant to a supplier, explains why now and helps the supplier identify who to contact. The engine combines normalised records, entity resolution, factual events, corroborated signals, inferred commercial needs, customer-specific relevance and contact enrichment. Planning applications and tenders are source events inside this chain, not products customers buy separately.$$),
('customer-profile-and-relevance', 'Customer profile and relevance', 'profile', $$Customers describe what they sell, who they sell to, where they sell and what types or sizes of businesses are a good fit. Free text is normalised by AI and deterministic mappings into services, target industries, relevant commercial needs, likely signal families and exclusions. Customers do not select a vertical or dataset. The same business can be highly relevant to an EPOS supplier, signage company or broadband provider and irrelevant to another supplier.$$),
('signal-families', 'Internal signal families', 'signals', $$The engine currently groups internal intelligence into six families: Hospitality Openings, Moves & Fit-Outs, Care & Health, Commercial Energy, Growing Businesses and Public Contracts. These are implementation categories, not customer subscriptions, add-ons or paywalls. All relevant families are available automatically and the supplier profile decides which opportunities appear.$$),
('commercial-needs', 'Commercial need inference', 'needs', $$A business change creates a commercial need which can become a sales opportunity. Hospitality openings may need EPOS, payments, broadband, signage, CCTV, commercial kitchens, waste, pest control, insurance, recruitment and fit-out. Office or commercial moves may need IT, managed services, internet connectivity, telephony, furniture, AV, CCTV, access control, cleaning, removals and signage. Care and health changes may need care software, recruitment, payroll, training, telecoms, IT, insurance, clinical waste and access control. Energy signals may indicate solar, HVAC, LED, insulation, glazing, EV charging or energy consultancy. Growing businesses may need recruitment, HR/payroll, IT, software, telecoms, office space and professional services. The inferred need is a commercial interpretation of evidence, not a guarantee of intent.$$),
('opportunity-brief', 'Opportunity brief structure', 'opportunities', $$A complete opportunity brief should answer four questions: which business should I approach, why is it relevant to what I sell, why now and who should I contact? The teaser can show approximate geography, opportunity type, fit score, buying-window summary, likely needs and corroborating signal count. The £20 unlock reveals the complete company and premises context, permitted contact detail, evidence trail, timeline, recommended next move and CRM actions. Scores should be explainable and evidence-grounded, not a mystery generated by an LLM.$$),
('coverage-and-unlocks', 'Coverage and lead unlocks', 'commercial', $$Local, Regional and Nationwide are geography plans only. Local is £29.99/month for one county, selected local towns or cities, or up to a 25-mile radius. Regional is £59.99/month for up to three neighbouring counties, a larger place group, or up to a 75-mile radius. Nationwide is £99.99/month for the UK. All relevant opportunities within coverage are included. The only additional charge is £20 for an individual lead unlock with permanent access for the customer company. There are no vertical subscriptions, source subscriptions, exclusive territories or lead bundles.$$),
('data-rights-and-evidence', 'Evidence, provenance and privacy', 'security', $$The platform must distinguish factual source evidence from inference. Show source dates, source links and provenance where the configured data rights allow it. Do not invent company, contact, address or decision-maker details. Contact fields are displayed or exported only when provider rights and the customer entitlement allow it. Teasers hide identity, exact address and contact context; the full brief is available after the individual lead unlock.$$),
('customer-outcomes', 'Customer outcomes and learning', 'workflow', $$Customers can save, dismiss, pursue, quote, win or lose an opportunity and record reasons such as wrong contact, not relevant, too early or too late. These outcomes help keep the marketplace useful and improve future relevance and scoring. CRM pushes and exports are actions on unlocked leads, not substitutes for the marketplace.$$),
('growth-engine', 'Internal growth engine', 'growth', $$The internal Growth Engine uses the same opportunity intelligence to identify potential customers for the platform. It finds suppliers such as EPOS providers, accountancy firms, office fit-out companies, internet and broadband providers, telecoms companies, signage firms, CCTV installers and other B2B service businesses. It builds a supplier profile, matches that supplier against current opportunity inventory, requires a meaningful threshold such as five relevant active opportunities including at least one Hot or Warm signal, and can produce a personalised teaser. Example: We currently have 14 businesses in your area showing signals that they may shortly require EPOS. This is internal customer acquisition, not a customer-facing vertical product.$$)
insert into public.assistant_knowledge_chunks (document_id, chunk_index, heading, content)
